mapper.select:
SELECT area_id, COUNT(1) AS userCount FROM member_user WHERE deleted = 0
AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
GROUP BY area_id

SELECT sex, COUNT(1) AS userCount FROM member_user WHERE deleted = 0
AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
GROUP BY sex

SELECT register_terminal as terminal, COUNT(1) AS userCount FROM member_user WHERE deleted = 0
AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
GROUP BY register_terminal

SELECT COUNT(1)
FROM member_user
WHERE deleted = 0

    AND create_time >= #{beginTime}


    AND create_time <= #{endTime}


    AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}

SELECT ${@cn.iocoder.yudao.framework.mybatis.core.util.SqlDialectUtils@castDate('create_time')} AS statDate,
       count(1)                             AS count
FROM member_user
WHERE create_time BETWEEN #{beginTime} AND #{endTime}
  AND deleted = 0

    AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}

GROUP BY ${@cn.iocoder.yudao.framework.mybatis.core.util.SqlDialectUtils@castDate('create_time')}
ORDER BY statDate
